// Markdown to HTML conversion table
const std::unordered_map<std::string, std::string> MARKDOWN_TO_HTML {
    {"#", "<h1>"},
    {"##", "<h2>"},
    {"###", "<h3>"},
    {"####", "<h4>"},
    {"#####", "<h5>"},
    {"######", "<h6>"},
    {"*", "<em>"},
    {"**", "<strong>"},
    {"`", "<code>"},
    {"[ ]", "<a></a>"},
    {"[ ]() ", "<a></a>"},
