    {"---", "<hr>"},
    {"\\*(\\S[\\S\\s]*)\\*", "<strong>$1</strong>"},
    {"(\\*)\\1", "<em>$1</em>"},
    {"__(\\S[\\S\\s]*)__", "<strong>$1</strong>"},
    {"_([^_])_", "<em>$1</em>"}
};

std::string convertMarkdownToHTML(std::string& markdown) {
    // Replace URLs in markdown with HTML links
    std::regex url_regex("https?://[^\s]*");
    std::string html = std::regex_replace(markdown, url_regex, "<a href=\"$0\"></a>");

    // Convert headers to HTML
    std::string new_markdown = std::regex_replace(markdown, std::regex("^([ #]+)[^\n]*"), [&](const std::smatch& match) {
        std::string header_level = match[1].str();
        std::string header_text = std::regex_replace(match[2].str(), std::regex(" {2,}"), "&nbsp;");
        return MARKDOWN_TO_HTML.at(header_level) + header_text + "</" + std::string(MARKDOWN_TO_HTML.find_first_of(header_level)) + ">\n";
    });

    // Convert inline formatting to HTML
    for (const auto& conversion : MARKDOWN_TO_HTML) {
        std::string find = conversion.first;
        std::string replace = conversion.second;
        new_markdown = std::regex_replace(new_markdown, std::regex(std::regex.escape(find)), replace);
    }

    return new_markdown;
}
```

